'replace' => function ($matches) {
    if (
        !(
            // 防止误伤
            $matches[1] == "十" && $matches[3] == "十"
            || $matches[1] == "十" && $matches[3] == "百"
            || $matches[1] == "十" && $matches[3] == "千"
        )
    ) {
        $matches[2] = str_replace("、", "", $matches[2]);
    }

    return $matches[1] . $matches[2] . $matches[3];
},
